261	        public static Matrix4x4 Inverse(Matrix4x4 m)
262	        {
263	            // Cramer's rule for 4x4
264	            float a2323 = m.m22 * m.m33 - m.m23 * m.m32;
265	            float a1323 = m.m21 * m.m33 - m.m23 * m.m31;
266	            float a1223 = m.m21 * m.m32 - m.m22 * m.m31;
267	            float a0323 = m.m20 * m.m33 - m.m23 * m.m30;
268	            float a0223 = m.m20 * m.m32 - m.m22 * m.m30;
269	            float a0123 = m.m20 * m.m31 - m.m21 * m.m30;
270	            float a2313 = m.m12 * m.m33 - m.m13 * m.m32;
271	            float a1313 = m.m11 * m.m33 - m.m13 * m.m31;
272	            float a1213 = m.m11 * m.m32 - m.m12 * m.m31;
273	            float a2312 = m.m12 * m.m23 - m.m13 * m.m22;
274	            float a1312 = m.m11 * m.m23 - m.m13 * m.m21;
275	            float a1212 = m.m11 * m.m22 - m.m12 * m.m21;
276	            float a0313 = m.m10 * m.m33 - m.m13 * m.m30;
277	            float a0213 = m.m10 * m.m32 - m.m12 * m.m30;
278	            float a0113 = m.m10 * m.m31 - m.m11 * m.m30;
279	            float a0312 = m.m10 * m.m23 - m.m13 * m.m20;
280	            float a0212 = m.m10 * m.m22 - m.m12 * m.m20;
281	            float a0112 = m.m10 * m.m21 - m.m11 * m.m20;
282	
283	            float det = m.m00 * (m.m11 * a2323 - m.m12 * a1323 + m.m13 * a1223)
284	                      - m.m01 * (m.m10 * a2323 - m.m12 * a0323 + m.m13 * a0223)
285	                      + m.m02 * (m.m10 * a1323 - m.m11 * a0323 + m.m13 * a0123)
286	                      - m.m03 * (m.m10 * a1223 - m.m11 * a0223 + m.m12 * a0123);
287	            float invDet = 1f / det;
288	
289	            var r = new Matrix4x4();
290	            r.m00 = invDet * (m.m11 * a2323 - m.m12 * a1323 + m.m13 * a1223);
291	            r.m01 = invDet * -(m.m01 * a2323 - m.m02 * a1323 + m.m03 * a1223);
292	            r.m02 = invDet * (m.m01 * a2313 - m.m02 * a1313 + m.m03 * a1213);
293	            r.m03 = invDet * -(m.m01 * a2312 - m.m02 * a1312 + m.m03 * a1212);
294	            r.m10 = invDet * -(m.m10 * a2323 - m.m12 * a0323 + m.m13 * a0223);
295	            r.m11 = invDet * (m.m00 * a2323 - m.m02 * a0323 + m.m03 * a0223);
296	            r.m12 = invDet * -(m.m00 * a2313 - m.m02 * a0313 + m.m03 * a0213);
297	            r.m13 = invDet * (m.m00 * a2312 - m.m02 * a0312 + m.m03 * a0212);
298	            r.m20 = invDet * (m.m10 * a1323 - m.m11 * a0323 + m.m13 * a0123);
299	            r.m21 = invDet * -(m.m00 * a1323 - m.m01 * a0323 + m.m03 * a0123);
300	            r.m22 = invDet * (m.m00 * a1313 - m.m01 * a0313 + m.m03 * a0113);
301	            r.m23 = invDet * -(m.m00 * a1312 - m.m01 * a0312 + m.m03 * a0112);
302	            r.m30 = invDet * -(m.m10 * a1223 - m.m11 * a0223 + m.m12 * a0123);
303	            r.m31 = invDet * (m.m00 * a1223 - m.m01 * a0223 + m.m02 * a0123);
304	            r.m32 = invDet * -(m.m00 * a1213 - m.m01 * a0213 + m.m02 * a0113);
305	            r.m33 = invDet * (m.m00 * a1212 - m.m01 * a0212 + m.m02 * a0112);
306	            return r;
