using System;
using System.Collections;
using System.Collections.Generic;

namespace UnityEngine
{
    public class Object
    {
        public string name;
        public int GetInstanceID() => GetHashCode();
        public static void Destroy(Object obj) { }
        public static void DestroyImmediate(Object obj) { }
        public static void DontDestroyOnLoad(Object obj) { }
        public static T Instantiate<T>(T original) where T : Object => original; // stub
        public static bool operator ==(Object a, Object b) => ReferenceEquals(a, null) == ReferenceEquals(b, null) && (ReferenceEquals(a, null) || ReferenceEquals(a, b));
        public static bool operator !=(Object a, Object b) => !(a == b);
        public static implicit operator bool(Object obj) => obj != null;
        public override bool Equals(object other) => ReferenceEquals(this, other);
        public override int GetHashCode() => base.GetHashCode();
    }

    public class Component : Object
    {
        public GameObject gameObject { get; set; }
        public Transform transform { get; set; }
        public T GetComponent<T>() where T : class => default;
        public T GetComponentInChildren<T>() where T : class => default;
        public T GetComponentInParent<T>() where T : class => default;
        public T[] GetComponentsInChildren<T>() => Array.Empty<T>();
        public bool TryGetComponent<T>(out T component) where T : class { component = default; return false; }
        public bool enabled { get; set; } = true;
    }

    public class Behaviour : Component { }

    public class MonoBehaviour : Behaviour
    {
        public bool isActiveAndEnabled => enabled;

        protected virtual void Awake() { }
