### Task 14: Wire Integration Bridges (Render, Audio, Input)

**Files:**
- Create: `BetterArc.Godot/Integration/GodotRenderBridge.cs`
- Create: `BetterArc.Godot/Integration/GodotAudioBridge.cs`
- Create: `BetterArc.Godot/Integration/GodotInputBridge.cs`
- Modify: `BetterArc.Godot/Integration/GameRoot.cs`

This is the task where the Shim stubs get replaced with real Godot implementations. This is NEW code and the primary place bugs can occur.

- [ ] **Step 1: Implement GodotRenderBridge**

This class intercepts `Graphics.DrawMesh()` calls from the Shim and renders them using Godot's `ImmediateMesh` or `MeshInstance3D`:

```csharp
using Godot;
using System.Collections.Generic;

namespace BetterArc.Integration
{
    public partial class GodotRenderBridge : Node3D
    {
        private readonly List<MeshInstance3D> _meshPool = new();
        private int _activeCount;

        public override void _Process(double delta)
        {
            // Reset pool each frame — ArcCreate re-submits all meshes every frame
            _activeCount = 0;
        }

        public void SubmitMesh(UnityEngine.Mesh unityMesh, UnityEngine.Matrix4x4 matrix, UnityEngine.Material material)
        {
            if (unityMesh?.vertices == null || unityMesh.vertices.Length == 0) return;

            var mi = GetOrCreateMeshInstance();
            mi.Mesh = ConvertMesh(unityMesh);
            mi.Transform = ConvertMatrix(matrix);
            // Material conversion happens in Phase 2 refinement
            mi.Visible = true;
        }

        private MeshInstance3D GetOrCreateMeshInstance()
        {
            if (_activeCount < _meshPool.Count)
                return _meshPool[_activeCount++];

            var mi = new MeshInstance3D();
            AddChild(mi);
            _meshPool.Add(mi);
            _activeCount++;
            return mi;
        }

        private static ArrayMesh ConvertMesh(UnityEngine.Mesh src)
        {
            var mesh = new ArrayMesh();
            var arrays = new Godot.Collections.Array();
            arrays.Resize((int)Mesh.ArrayType.Max);

            var verts = new Vector3[src.vertices.Length];
            for (int i = 0; i < src.vertices.Length; i++)
                verts[i] = new Vector3(src.vertices[i].x, src.vertices[i].y, src.vertices[i].z);
            arrays[(int)Mesh.ArrayType.Vertex] = verts;

            if (src.triangles != null)
                arrays[(int)Mesh.ArrayType.Index] = src.triangles;

            if (src.uv != null)
            {
                var uvs = new Vector2[src.uv.Length];
                for (int i = 0; i < src.uv.Length; i++)
                    uvs[i] = new Vector2(src.uv[i].x, src.uv[i].y);
                arrays[(int)Mesh.ArrayType.TexUV] = uvs;
            }

            if (src.colors != null)
            {
                var colors = new Godot.Color[src.colors.Length];
                for (int i = 0; i < src.colors.Length; i++)
                    colors[i] = new Godot.Color(src.colors[i].r, src.colors[i].g, src.colors[i].b, src.colors[i].a);
                arrays[(int)Mesh.ArrayType.Color] = colors;
            }

            mesh.AddSurfaceFromArrays(Mesh.PrimitiveType.Triangles, arrays);
            return mesh;
        }

        private static Transform3D ConvertMatrix(UnityEngine.Matrix4x4 m)
        {
            return new Transform3D(
                new Basis(
                    new Vector3(m.m00, m.m10, m.m20),
                    new Vector3(m.m01, m.m11, m.m21),
                    new Vector3(m.m02, m.m12, m.m22)),
                new Vector3(m.m03, m.m13, m.m23));
        }
    }
}
```

- [ ] **Step 2: Implement GodotAudioBridge**

```csharp
using Godot;
using System.Collections.Generic;

namespace BetterArc.Integration
{
    public partial class GodotAudioBridge : Node
    {
        private AudioStreamPlayer _musicPlayer;
        private readonly Dictionary<string, AudioStream> _sfxCache = new();
        private readonly List<AudioStreamPlayer> _sfxPool = new();

        public override void _Ready()
        {
            _musicPlayer = new AudioStreamPlayer();
            AddChild(_musicPlayer);

            for (int i = 0; i < 8; i++)
            {
                var player = new AudioStreamPlayer();
                AddChild(player);
                _sfxPool.Add(player);
            }
        }

        public void LoadMusic(string path)
        {
            var stream = ResourceLoader.Load<AudioStream>(path);
            if (stream != null) _musicPlayer.Stream = stream;
        }

        public void PlayMusic() => _musicPlayer.Play();
        public void PauseMusic() => _musicPlayer.StreamPaused = true;
        public void ResumeMusic() => _musicPlayer.StreamPaused = false;
        public float GetMusicTime() => (float)_musicPlayer.GetPlaybackPosition();
        public void SetMusicTime(float time) => _musicPlayer.Seek(time);

        public void PlaySfx(string path)
        {
            if (!_sfxCache.TryGetValue(path, out var stream))
            {
                stream = ResourceLoader.Load<AudioStream>(path);
                if (stream != null) _sfxCache[path] = stream;
            }

            foreach (var player in _sfxPool)
            {
                if (!player.Playing)
                {
                    player.Stream = stream;
                    player.Play();
                    return;
                }
            }
        }
    }
}
```

- [ ] **Step 3: Implement GodotInputBridge**

```csharp
using Godot;
using System.Collections.Generic;

namespace BetterArc.Integration
{
    public partial class GodotInputBridge : Node
    {
        private readonly List<UnityEngine.Touch> _activeTouches = new();

        public override void _Input(InputEvent @event)
        {
            if (@event is InputEventScreenTouch touch)
            {
                if (touch.Pressed)
                {
                    _activeTouches.Add(new UnityEngine.Touch
                    {
                        fingerId = touch.Index,
                        position = new UnityEngine.Vector2(touch.Position.X, touch.Position.Y),
                        phase = UnityEngine.TouchPhase.Began
                    });
                }
                else
                {
                    _activeTouches.RemoveAll(t => t.fingerId == touch.Index);
                }
            }
            else if (@event is InputEventScreenDrag drag)
            {
                for (int i = 0; i < _activeTouches.Count; i++)
                {
                    if (_activeTouches[i].fingerId == drag.Index)
                    {
                        var t = _activeTouches[i];
                        t.position = new UnityEngine.Vector2(drag.Position.X, drag.Position.Y);
                        t.phase = UnityEngine.TouchPhase.Moved;
                        _activeTouches[i] = t;
                    }
                }
            }
        }

        public override void _Process(double delta)
        {
            // Update shim Input state
            // This allows ArcCreate's Input.touchCount / Input.GetTouch to work
        }

        public int TouchCount => _activeTouches.Count;
        public UnityEngine.Touch GetTouch(int index) => _activeTouches[index];
    }
}
```

